1	/**
2	 * @module features/tv-dashboard/ui/TvDashboard.page
3	 *
4	 * Página `/tv` — Torre de Controle da Operação. Dentro do DashboardLayout
5	 * (sidebar visível). Full-bleed via DashboardLayout.isFullBleedPage.
6	 * Usa MommaPageLayout como todas as outras páginas do sistema.
7	 */
8	
9	import { useMemo, useState } from 'react';
10	import { useNavigate } from 'react-router-dom';
11	import { ArrowLeft, Settings2 } from 'lucide-react';
12	import type { TvPeriod } from '../model/types';
13	import { useTvDashboardData } from '../model/useTvDashboardData';
14	import { useTvRealtime } from '../model/useTvRealtime';
15	import { TvHero } from './TvHero';
16	import { TvStoreColumn } from './TvStoreColumn';
17	import { TvFabricaColumn } from './TvFabricaColumn';
18	import { useMinuteClock } from '../model/useMinuteClock';
19	import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
20	import { GlassCard } from '@/shared/ui/glass-card';
21	import './tv.css';
22	
23	/** Skeleton de uma coluna no estado de loading inicial. */
24	function TvColumnSkeleton({ delay = 0 }: { delay?: number }) {
25	  return (
26	    <div
27	      className="overflow-hidden rounded-2xl bg-white/60 p-4 backdrop-blur-xl saturate-150 border border-[#57715B]/10 animate-pulse"
28	      style={{ animationDelay: `${delay}ms` }}
29	    >
30	      <div className="space-y-3">
31	        <div className="h-4 w-2/3 rounded-full bg-[#57715B]/10" />
32	        <div className="h-10 w-3/4 rounded-full bg-[#57715B]/10" />
33	        <div className="h-2 w-full rounded-full bg-[#57715B]/10" />
34	        <div className="h-3 w-1/2 rounded-full bg-[#57715B]/10" />
35	        <div className="mt-4 space-y-2">
36	          <div className="h-3 w-full rounded bg-[#57715B]/6" />
37	          <div className="h-3 w-4/5 rounded bg-[#57715B]/6" />
38	        </div>
39	      </div>
40	    </div>
41	  );
42	}
43	
44	/** Card de erro quando contexto não carrega. */
45	function TvErrorCard() {
46	  return (
47	    <GlassCard variant="premium" className="flex flex-col p-4 min-h-[160px]">
48	      <div className="flex items-center justify-between gap-3">
49	        <span className="font-momma text-base font-semibold text-[#7C887E]">—</span>
50	        <span className="inline-flex items-center rounded-full border border-amber-400/40 bg-amber-50 px-3 py-0.5 font-momma text-sm font-medium text-amber-600">
51	          sem conexão
52	        </span>
53	      </div>
54	      <span className="mt-4 font-momma text-4xl font-bold leading-none text-[#7C887E]">—</span>
55	    </GlassCard>
56	  );
57	}
58	
59	const COL_ENTER_CLS = [
60	  'tv-col-enter tv-col-enter-1',
61	  'tv-col-enter tv-col-enter-2',
62	  'tv-col-enter tv-col-enter-3',
63	  'tv-col-enter tv-col-enter-4',
64	  'tv-col-enter tv-col-enter-5',
65	  'tv-col-enter tv-col-enter-6',
66	] as const;
67	
68	/** Página raiz do painel TV — Torre de Controle da Operação. */
69	export default function TvDashboardPage() {
70	  const navigate = useNavigate();
71	  const [period, setPeriod] = useState<TvPeriod>('today');
72	  const data = useTvDashboardData(period);
73	  useTvRealtime();
74	  const now = useMinuteClock();
75	
76	  const rankedStores = useMemo(() => {
77	    if (!data.stores) return [] as typeof data.stores;
78	    return data.stores.map((s, _, arr) => {
79	      const vendas = s.vendas?.valor ?? 0;
80	      const rank =
81	        vendas > 0 ? arr.filter((x) => (x.vendas?.valor ?? 0) > vendas).length + 1 : null;
82	      return { ...s, rank };
83	    });
84	  }, [data.stores]);
85	
86	  if (data.isLoading) {
87	    return (
88	      <MommaPageLayout>
89	        <div className="p-4 sm:p-6 space-y-4 font-momma">
90	          <div className="h-32 rounded-2xl bg-white/60 backdrop-blur-xl border border-[#57715B]/10 animate-pulse" />
91	          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
92	            {Array.from({ length: 6 }, (_, i) => (
93	              <TvColumnSkeleton key={i} delay={i * 60} />
94	            ))}
95	          </div>
96	        </div>
97	      </MommaPageLayout>
98	    );
99	  }
100	
101	  const storeCards = rankedStores.slice(0, data.factory ? 5 : 6);
102	  const totalCols = storeCards.length + (data.factory ? 1 : 0);
103	
104	  return (
105	    <MommaPageLayout>
106	      <div
107	        className="flex flex-col gap-4 p-4 sm:p-6 font-momma text-[#2D362E]"
108	        data-testid="tv-dashboard"
109	      >
110	        {/* Header: botão voltar mobile + título + botão metas */}
111	        <div className="flex items-center justify-between gap-3">
112	          <button
113	            type="button"
114	            onClick={() => navigate(-1)}
115	            className="flex items-center gap-1.5 rounded-full border border-[#57715B]/20 bg-white/70 px-3 py-1.5 text-sm font-medium text-[#57715B] backdrop-blur-sm transition-colors hover:bg-[#57715B]/10 lg:hidden"
116	            aria-label="Voltar"
117	          >
118	            <ArrowLeft className="h-4 w-4" aria-hidden />
119	            Voltar
120	          </button>
121	          <h1 className="hidden text-lg font-semibold text-[#2D362E] lg:block">
122	            Torre de Controle
123	          </h1>
124	          <button
125	            type="button"
126	            onClick={() => navigate('/tv/metas')}
127	            data-mia-action="abrir-metas-painel-tv"
128	            className="flex items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-4 py-1.5 text-sm font-medium text-[#57715B] shadow-sm backdrop-blur-md transition-colors hover:bg-[#57715B]/10"
129	          >
130	            <Settings2 className="h-4 w-4" aria-hidden />
131	            Metas
132	          </button>
133	        </div>
134	
135	        {/* Hero: vendas da rede, marketing, perdas, filtro período */}
136	        <TvHero
137	          network={data.network}
138	          freshness={data.freshness}
139	          now={now}
140	          period={period}
141	          onPeriodChange={setPeriod}
142	        />
143	
144	        {/* Grid de colunas com scroll horizontal em telas estreitas */}
145	        <div className="overflow-x-auto pb-2 -mx-4 px-4 sm:-mx-6 sm:px-6">
146	          <div
147	            className={[
148	              'grid gap-4',
149	              totalCols <= 3 ? 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3' : 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6',
150	            ].join(' ')}
151	            style={{ minWidth: `${totalCols * 230}px` }}
152	          >
153	            {data.isError ? (
154	              Array.from({ length: 6 }, (_, i) => <TvErrorCard key={i} />)
155	            ) : (
156	              <>
157	                {storeCards.map((store, idx) => (
158	                  <div
159	                    key={store.lojaId}
160	                    className={`flex flex-col ${COL_ENTER_CLS[idx] ?? 'tv-col-enter tv-col-enter-1'}`}
161	                  >
162	                    <TvStoreColumn
163	                      store={store}
164	                      liveLevel={data.freshness.vendasLive.level}
165	                      period={period}
166	                      now={now}
167	                      rank={store.rank}
168	                    />
169	                  </div>
170	                ))}
171	                {data.factory && (
172	                  <div
173	                    className={`flex flex-col ${COL_ENTER_CLS[storeCards.length] ?? 'tv-col-enter tv-col-enter-6'}`}
174	                  >
175	                    <TvFabricaColumn
176	                      factory={data.factory}
177	                      freshness={data.freshness}
178	                      period={period}
179	                      now={now}
180	                    />
181	                  </div>
182	                )}
183	              </>
184	            )}
185	          </div>
186	        </div>
187	      </div>
188	    </MommaPageLayout>
189	  );
190	}
191

1	/**
2	 * @module features/tv-dashboard/ui/TvHero
3	 *
4	 * Hero v3 da Torre de Controle: vendas da rede HOJE + % vs ONTEM
5	 * (comparativo principal; barra de meta pró-rata vira secundária),
6	 * COMPRAS e PERDAS do período do filtro global, contador de alertas
7	 * críticos, relógio + freshness e o FILTRO GLOBAL Hoje/Semana/Mês
8	 * (segmented control glass — muda perdas/compras/comparativos).
9	 *
10	 * Linha 1: marca + (freshness · relógio · filtro). Linha 2: métricas.
11	 * Mobile empilha; lg+ vira a faixa de 4 zonas.
12	 */
13	
14	import { ArrowDown, ArrowUp, RefreshCw } from 'lucide-react';
15	import type { TvFreshness, TvNetworkSummary, TvPeriod } from '../model/types';
16	import { formatCompactBRL } from '../model/tvMath';
17	import { TvDeltaChip, TvMetaBar } from './TvChips';
18	import {
19	  TV_PERIOD_LABEL,
20	  expectedPctNow,
21	  formatDeltaPct,
22	  formatTimeHHMM,
23	  metaBarColorFromRatio,
24	} from './tvFormat';
25	import { useCountUp } from './useCountUp';
26	
27	interface TvHeroProps {
28	  network: TvNetworkSummary | null;
29	  freshness: TvFreshness;
30	  now: Date;
31	  /** Período do filtro global (controlado pela página). */
32	  period: TvPeriod;
33	  onPeriodChange: (period: TvPeriod) => void;
34	}
35	
36	const PERIOD_OPTIONS: ReadonlyArray<{ value: TvPeriod; label: string }> = [
37	  { value: 'today', label: 'Hoje' },
38	  { value: 'week', label: 'Semana' },
39	  { value: 'month', label: 'Mês' },
40	];
41	
42	/** Segmented control glass do filtro global (Hoje/Semana/Mês). */
43	function TvPeriodFilter({
44	  period,
45	  onPeriodChange,
46	}: {
47	  period: TvPeriod;
48	  onPeriodChange: (period: TvPeriod) => void;
49	}) {
50	  return (
51	    <div
52	      className="inline-flex shrink-0 items-center rounded-full border border-[#57715B]/15 bg-white/60 p-1 backdrop-blur-md"
53	      role="group"
54	      aria-label="Período de perdas, compras e comparativos"
55	      data-testid="tv-period-filter"
56	    >
57	      {PERIOD_OPTIONS.map((opt) => {
58	        const active = opt.value === period;
59	        return (
60	          <button
61	            key={opt.value}
62	            type="button"
63	            aria-pressed={active}
64	            data-mia-action={`filtrar-painel-tv-periodo-${opt.value}`}
65	            onClick={() => onPeriodChange(opt.value)}
66	            className={`rounded-full px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium leading-none transition-colors motion-reduce:transition-none lg:px-4 lg:py-1.5 ${
67	              active
68	                ? 'bg-[#57715B] text-white shadow-sm'
69	                : 'text-[#5F6F63] hover:bg-[#57715B]/10'
70	            }`}
71	          >
72	            {opt.label}
73	          </button>
74	        );
75	      })}
76	    </div>
77	  );
78	}
79	
80	/**
81	 * Linha de delta vs período anterior (compras/perdas). Neutra por padrão;
82	 * âmbar SÓ no desvio ruim (`amberWhenUp`: perdas subindo). Sem base → texto
83	 * honesto "sem base anterior".
84	 */
85	function TvHeroDeltaLine({
86	  deltaPct,
87	  amberWhenUp = false,
88	}: {
89	  deltaPct: number | null;
90	  amberWhenUp?: boolean;
91	}) {
92	  if (deltaPct == null) {
93	    return (
94	      <span className="font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] text-[#7C887E]">
95	        sem base anterior
96	      </span>
97	    );
98	  }
99	  const isAmber = amberWhenUp && deltaPct > 0;
100	  const Icon = deltaPct < 0 ? ArrowDown : ArrowUp;
101	  return (
102	    <span
103	      className={`inline-flex items-center gap-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium tabular-nums ${
104	        isAmber ? 'text-amber-600' : 'text-[#7C887E]'
105	      }`}
106	    >
107	      <Icon className="h-[1em] w-[1em] shrink-0" aria-hidden />
108	      {formatDeltaPct(deltaPct)} vs anterior
109	    </span>
110	  );
111	}
112	
113	/** Hero da rede (v3): marca/relógio/filtro + faixa de métricas. */
114	export function TvHero({ network, freshness, now, period, onPeriodChange }: TvHeroProps) {
115	  const vendas = useCountUp(network?.vendasHoje ?? 0);
116	  const hasData = network != null;
117	  const periodLabel = TV_PERIOD_LABEL[period];
118	
119	  // Barra de meta (SECUNDÁRIA na v3): preenchimento = % do dia COMPLETO;
120	  // tick dourado = esperado agora (pró-rata).
121	  const fullDayPct =
122	    network && network.metaDia != null && network.metaDia > 0
123	      ? (network.vendasHoje / network.metaDia) * 100
124	      : null;
125	  const expected = expectedPctNow(now);
126	  const ratio = network?.pctMetaProRata != null ? network.pctMetaProRata / 100 : null;
127	  const barColor = metaBarColorFromRatio(ratio, now);
128	
129	  const liveFresh = freshness.vendasLive.level === 'fresh';
130	  const liveTime = formatTimeHHMM(freshness.vendasLive.updatedAt);
131	
132	  return (
133	    <header
134	      className="flex flex-col gap-4 border-b border-[#C5A065]/25 pb-4 lg:gap-5"
135	      data-testid="tv-hero"
136	    >
137	      {/* Linha 1 — marca + relógio/freshness/filtro global */}
138	      <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3">
139	        <div className="flex min-w-0 items-baseline gap-3">
140	          <span className="font-momma text-[clamp(0.875rem,1.05vw,1.875rem)] font-bold uppercase tracking-[0.3em] text-[#C5A065]">
141	            MOMMA
142	          </span>
143	          <span className="truncate font-serif text-[clamp(1rem,1.35vw,2.5rem)] font-semibold tracking-tight text-[#2D362E]">
144	            Torre de Controle
145	          </span>
146	        </div>
147	        <div className="flex flex-wrap items-center gap-x-4 gap-y-2 lg:gap-x-5">
148	          <span className={`inline-flex items-center gap-2 rounded-full px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium ${
149	            liveFresh
150	              ? 'bg-emerald-50 text-emerald-600'
151	              : 'border border-amber-400/40 bg-amber-50 text-amber-600'
152	          }`}>
153	            {liveFresh
154	              ? <><span className="h-2 w-2 rounded-full bg-emerald-400 animate-pulse" aria-hidden />{liveTime || 'ao vivo'}</>
155	              : <><RefreshCw className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />{liveTime ? `último ${liveTime}` : 'atrasado'}</>
156	            }
157	          </span>
158	          <span className="font-momma text-[clamp(1.25rem,2vw,3.75rem)] font-light leading-none text-[#2D362E] tabular-nums">
159	            {formatTimeHHMM(now)}
160	          </span>
161	          <TvPeriodFilter period={period} onPeriodChange={onPeriodChange} />
162	        </div>
163	      </div>
164	
165	      {/* Linha 2 — métricas: vendas | compras | perdas | alertas */}
166	      <div className="grid grid-cols-2 items-end gap-x-4 gap-y-4 lg:grid-cols-3 lg:gap-8">
167	        {/* Zona 1 — vendas da rede hoje + % vs ontem (principal) */}
168	        <div className="col-span-2 min-w-0 lg:col-span-1">
169	          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
170	            REDE · VENDAS HOJE
171	          </span>
172	          <div className="mt-1 flex flex-wrap items-end gap-x-4 gap-y-2">
173	            <span
174	              className="font-momma text-[clamp(2.25rem,4vw,7.5rem)] font-bold leading-none text-[#2D362E] tabular-nums"
175	              data-testid="tv-hero-sales"
176	            >
177	              {hasData ? formatCompactBRL(vendas) : '—'}
178	            </span>
179	            {network?.deltaOntem != null && (
180	              <span className="pb-1">
181	                <TvDeltaChip delta={network.deltaOntem} label="ontem" size="hero" />
182	              </span>
183	            )}
184	            {network?.deltaSemana != null && period === 'week' && (
185	              <span className="pb-1">
186	                <TvDeltaChip delta={network.deltaSemana} label="sem. ant." size="hero" />
187	              </span>
188	            )}
189	          </div>
190	          {/* Meta pró-rata — secundária desde a v3 */}
191	          <div className="mt-2 max-w-[36rem]">
192	            <TvMetaBar
193	              fillPct={fullDayPct}
194	              expectedPct={fullDayPct != null ? expected : null}
195	              color={barColor}
196	              size="card"
197	            />
198	            <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] leading-tight">
199	              {fullDayPct != null ? (
200	                <>
201	                  <span className="font-medium text-[#5F6F63]">
202	                    {Math.round(fullDayPct)}% da meta
203	                  </span>
204	                  <span className="text-[#7C887E]"> · esperado {expected}%</span>
205	                </>
206	              ) : (
207	                <span className="text-[#7C887E]">sem meta cadastrada</span>
208	              )}
209	            </p>
210	          </div>
211	        </div>
212	
213	        {/* Zona 2 — marketing do período */}
214	        <div className="min-w-0">
215	          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
216	            MARKETING · {periodLabel}
217	          </span>
218	          <p
219	            className="mt-1 font-momma text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold leading-none text-[#2D362E] tabular-nums"
220	            data-testid="tv-hero-marketing"
221	          >
222	            {network ? formatCompactBRL(network.marketing.valor) : '—'}
223	          </p>
224	          <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] text-[#7C887E]">
225	            {network ? `${network.marketing.acoes} ${network.marketing.acoes === 1 ? 'ação' : 'ações'}` : '—'}
226	          </p>
227	        </div>
228	
229	        {/* Zona 3 — perdas do período (R$ + itens; subir é desvio → âmbar) */}
230	        <div className="min-w-0">
231	          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
232	            PERDAS · {periodLabel}
233	          </span>
234	          <p
235	            className="mt-1 font-momma text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold leading-none text-[#2D362E] tabular-nums"
236	            data-testid="tv-hero-perdas"
237	          >
238	            {network ? formatCompactBRL(network.perdas.valor) : '—'}
239	            {network && (
240	              <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
241	                {' '}
242	                · {network.perdas.itens} {network.perdas.itens === 1 ? 'item' : 'itens'}
243	              </span>
244	            )}
245	          </p>
246	          <p className="mt-1">
247	            <TvHeroDeltaLine deltaPct={network?.perdas.deltaPct ?? null} amberWhenUp />
248	          </p>
249	        </div>
250	
251	      </div>
252	    </header>
253	  );
254	}
255

input.command:
cd "C:\Users\olive_\OneDrive\Documentos\codigo\Momma\momma-stock-insight" && MODEL=gemini-3.1-pro-preview bash scripts/gemini-dispatch.sh <<'PROMPT_START'
Você é um engenheiro frontend sênior especialista em React 18 + TypeScript 5 strict para o MommaERP (Gidape) — ERP interno de uma confeitaria artesanal saudável (Momma, Brasília, Brasil). Multi-loja, Supabase backend.

═══════════════════════════════════════════════════
DESIGN SYSTEM — FONTE DA VERDADE (ler com atenção)
═══════════════════════════════════════════════════

⚠️ ALERTA CRÍTICO: `src/index.css` tem variáveis CSS `:root` com bege (#F3ECD4), marrom (#B49364),
tokens --pantone-*, --company-* — TUDO ISSO É LEGADO ABANDONADO. Ignorar completamente.
A identidade real é glassmorphism verde sage sobre fundo branco, descrita abaixo.

IDENTIDADE VISUAL:
- Verde sage #57715B é a COR DA MARCA (2.300+ ocorrências no projeto)
- Fundo: bg-white dark:bg-[#0A0A0A] com superfícies de vidro translúcido
- Dourado #C5A065: APENAS acento sutil (glow, hover shadow) — nunca superfície ou texto
- Sensação: confeitaria premium, leve, orgânica

GRAMÁTICA VISUAL (classes Tailwind exatas):

1. FUNDO DE PÁGINA — sempre via <MommaPageLayout>:
   bg-white dark:bg-[#0A0A0A] + awning stripe verde no topo
   (repeating-linear-gradient #57715B/branco) + folhas opacity-[0.03]
   + ambient glows: bg-[#57715B]/5 e bg-[#C5A065]/5 blur-[80px]

2. GLASS CARD PADRÃO:
   bg-white/40 dark:bg-black/20 backdrop-blur-md border-white/20 dark:border-white/10
   rounded-2xl shadow-sm hover:shadow-md

3. GLASS CARD PREMIUM (GlassCard component):
   bg-white/60 dark:bg-black/20 backdrop-blur-xl saturate-150
   border-white/50 dark:border-white/10 rounded-[2rem]
   shadow-[0_8px_32px_rgba(0,0,0,0.12)]
   + gradiente interno from-white/40 via-transparent to-[#C5A065]/5

4. KPI CARD:
   bg-white/60 dark:bg-[#1A1A1A]/60 rounded-[2rem] p-5
   border border-[#57715B]/10 shadow-sm hover:shadow-md backdrop-blur-md
   ícone watermark: absolute top-0 right-0 opacity-10 group-hover:opacity-20
   label: text-xs font-semibold uppercase tracking-wider text-muted-foreground
   valor: text-2xl font-bold text-[#2D362E] dark:text-[#E6DCCF] tabular-nums

5. TIPOGRAFIA:
   Font: Poppins (font-momma ou font-sans herdado)
   Títulos de página: text-2xl md:text-4xl font-bold tracking-tight font-serif
   Subtítulos: text-xs md:text-sm uppercase tracking-widest
   Números importantes: font-bold tabular-nums

