/**
 * @module features/tv-dashboard/ui/TvDashboard.page
 *
 * Página `/tv` — Torre de Controle da Operação. Dentro do DashboardLayout
 * (sidebar visível). Full-bleed via DashboardLayout.isFullBleedPage.
 * Usa MommaPageLayout como todas as outras páginas do sistema.
 */

import { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Settings2 } from 'lucide-react';
import type { TvPeriod } from '../model/types';
import { useTvDashboardData } from '../model/useTvDashboardData';
import { useTvRealtime } from '../model/useTvRealtime';
import { TvHero } from './TvHero';
import { TvStoreColumn } from './TvStoreColumn';
import { TvFabricaColumn } from './TvFabricaColumn';
import { useMinuteClock } from '../model/useMinuteClock';
import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
import { GlassCard } from '@/shared/ui/glass-card';
import './tv.css';

/** Skeleton de uma coluna no estado de loading inicial. */
function TvColumnSkeleton({ delay = 0 }: { delay?: number }) {
  return (
    <div
      className="overflow-hidden rounded-2xl bg-white/60 p-4 backdrop-blur-xl saturate-150 border border-[#57715B]/10 animate-pulse"
      style={{ animationDelay: `${delay}ms` }}
    >
      <div className="space-y-3">
        <div className="h-4 w-2/3 rounded-full bg-[#57715B]/10" />
        <div className="h-10 w-3/4 rounded-full bg-[#57715B]/10" />
        <div className="h-2 w-full rounded-full bg-[#57715B]/10" />
        <div className="h-3 w-1/2 rounded-full bg-[#57715B]/10" />
        <div className="mt-4 space-y-2">
          <div className="h-3 w-full rounded bg-[#57715B]/6" />
          <div className="h-3 w-4/5 rounded bg-[#57715B]/6" />
        </div>
      </div>
    </div>
  );
}

/** Card de erro quando contexto não carrega. */
function TvErrorCard() {
  return (
    <GlassCard variant="premium" className="flex flex-col p-4 min-h-[160px]">
      <div className="flex items-center justify-between gap-3">
        <span className="font-momma text-base font-semibold text-[#7C887E]">—</span>
        <span className="inline-flex items-center rounded-full border border-amber-400/40 bg-amber-50 px-3 py-0.5 font-momma text-sm font-medium text-amber-600">
          sem conexão
        </span>
      </div>
      <span className="mt-4 font-momma text-4xl font-bold leading-none text-[#7C887E]">—</span>
    </GlassCard>
  );
}

const COL_ENTER_CLS = [
  'tv-col-enter tv-col-enter-1',
  'tv-col-enter tv-col-enter-2',
  'tv-col-enter tv-col-enter-3',
  'tv-col-enter tv-col-enter-4',
  'tv-col-enter tv-col-enter-5',
  'tv-col-enter tv-col-enter-6',
] as const;

/** Página raiz do painel TV — Torre de Controle da Operação. */
export default function TvDashboardPage() {
  const navigate = useNavigate();
  const [period, setPeriod] = useState<TvPeriod>('today');
  const data = useTvDashboardData(period);
  useTvRealtime();
  const now = useMinuteClock();

  const rankedStores = useMemo(() => {
    if (!data.stores) return [] as typeof data.stores;
    return data.stores.map((s, _, arr) => {
      const vendas = s.vendas?.valor ?? 0;
      const rank =
        vendas > 0 ? arr.filter((x) => (x.vendas?.valor ?? 0) > vendas).length + 1 : null;
      return { ...s, rank };
    });
  }, [data.stores]);

  if (data.isLoading) {
    return (
      <MommaPageLayout>
        <div className="p-4 sm:p-6 space-y-4 font-momma">
          <div className="h-32 rounded-2xl bg-white/60 backdrop-blur-xl border border-[#57715B]/10 animate-pulse" />
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {Array.from({ length: 6 }, (_, i) => (
              <TvColumnSkeleton key={i} delay={i * 60} />
            ))}
          </div>
        </div>
      </MommaPageLayout>
    );
  }

  const storeCards = rankedStores.slice(0, data.factory ? 5 : 6);

  return (
    <MommaPageLayout>
      <div
        className="flex flex-col gap-4 p-4 sm:p-6 font-momma text-[#2D362E]"
        data-testid="tv-dashboard"
      >
        {/* Header: botão voltar mobile + botão metas */}
        <div className="flex items-center justify-between gap-3">
          <button
            type="button"
            onClick={() => navigate(-1)}
            className="flex items-center gap-1.5 rounded-full border border-[#57715B]/20 bg-white/70 px-3 py-1.5 text-sm font-medium text-[#57715B] backdrop-blur-sm transition-colors hover:bg-[#57715B]/10 lg:hidden"
            aria-label="Voltar"
          >
            <ArrowLeft className="h-4 w-4" aria-hidden />
            Voltar
          </button>
          <button
            type="button"
            onClick={() => navigate('/tv/metas')}
            data-mia-action="abrir-metas-painel-tv"
            className="flex items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-4 py-1.5 text-sm font-medium text-[#57715B] shadow-sm backdrop-blur-md transition-colors hover:bg-[#57715B]/10"
          >
            <Settings2 className="h-4 w-4" aria-hidden />
            Metas
          </button>
        </div>

        {/* Hero: vendas da rede, marketing, perdas, filtro período */}
        <TvHero
          network={data.network}
          freshness={data.freshness}
          now={now}
          period={period}
          onPeriodChange={setPeriod}
        />

        {/* Grid de colunas — responsivo, sem scroll horizontal */}
        <div>
          <div className="grid gap-4 grid-cols-2 sm:grid-cols-3 lg:grid-cols-6">
            {data.isError ? (
              Array.from({ length: 6 }, (_, i) => <TvErrorCard key={i} />)
            ) : (
              <>
                {storeCards.map((store, idx) => (
                  <div
                    key={store.lojaId}
                    className={`flex min-w-0 flex-col ${COL_ENTER_CLS[idx] ?? 'tv-col-enter tv-col-enter-1'}`}
                  >
                    <TvStoreColumn
                      store={store}
                      liveLevel={data.freshness.vendasLive.level}
                      period={period}
                      now={now}
                      rank={store.rank}
                    />
                  </div>
                ))}
                {data.factory && (
                  <div
                    className={`flex min-w-0 flex-col ${COL_ENTER_CLS[storeCards.length] ?? 'tv-col-enter tv-col-enter-6'}`}
                  >
                    <TvFabricaColumn
                      factory={data.factory}
                      freshness={data.freshness}
                      period={period}
                      now={now}
                    />
                  </div>
                )}
              </>
            )}
          </div>
        </div>
      </div>
    </MommaPageLayout>
  );
}

/**
 * @module features/tv-dashboard/ui/TvHero
 *
 * Hero v3 da Torre de Controle: vendas da rede HOJE + % vs ONTEM
 * (comparativo principal; barra de meta pró-rata vira secundária),
 * COMPRAS e PERDAS do período do filtro global, contador de alertas
 * críticos, relógio + freshness e o FILTRO GLOBAL Hoje/Semana/Mês
 * (segmented control glass — muda perdas/compras/comparativos).
 *
 * Linha 1: marca + (freshness · relógio · filtro). Linha 2: métricas.
 * Mobile empilha; lg+ vira a faixa de 4 zonas.
 */

import { ArrowDown, ArrowUp, RefreshCw } from 'lucide-react';
import type { TvFreshness, TvNetworkSummary, TvPeriod } from '../model/types';
import { formatCompactBRL } from '../model/tvMath';
import { TvDeltaChip, TvMetaBar } from './TvChips';
import {
  TV_PERIOD_LABEL,
  expectedPctNow,
  formatDeltaPct,
  formatTimeHHMM,
  metaBarColorFromRatio,
} from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvHeroProps {
  network: TvNetworkSummary | null;
  freshness: TvFreshness;
  now: Date;
  /** Período do filtro global (controlado pela página). */
  period: TvPeriod;
  onPeriodChange: (period: TvPeriod) => void;
}

const PERIOD_OPTIONS: ReadonlyArray<{ value: TvPeriod; label: string }> = [
  { value: 'today', label: 'Hoje' },
  { value: 'week', label: 'Semana' },
  { value: 'month', label: 'Mês' },
];

/** Segmented control glass do filtro global (Hoje/Semana/Mês). */
function TvPeriodFilter({
  period,
  onPeriodChange,
}: {
  period: TvPeriod;
  onPeriodChange: (period: TvPeriod) => void;
}) {
  return (
    <div
      className="inline-flex shrink-0 items-center rounded-full border border-[#57715B]/15 bg-white/60 p-1 backdrop-blur-md"
      role="group"
      aria-label="Período de perdas, compras e comparativos"
      data-testid="tv-period-filter"
    >
      {PERIOD_OPTIONS.map((opt) => {
        const active = opt.value === period;
        return (
          <button
            key={opt.value}
            type="button"
            aria-pressed={active}
            data-mia-action={`filtrar-painel-tv-periodo-${opt.value}`}
            onClick={() => onPeriodChange(opt.value)}
            className={`rounded-full px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium leading-none transition-colors motion-reduce:transition-none lg:px-4 lg:py-1.5 ${
              active
                ? 'bg-[#57715B] text-white shadow-sm'
                : 'text-[#5F6F63] hover:bg-[#57715B]/10'
            }`}
          >
            {opt.label}
          </button>
        );
      })}
    </div>
  );
}

/**
 * Linha de delta vs período anterior (compras/perdas). Neutra por padrão;
 * âmbar SÓ no desvio ruim (`amberWhenUp`: perdas subindo). Sem base → texto
 * honesto "sem base anterior".
 */
function TvHeroDeltaLine({
  deltaPct,
  amberWhenUp = false,
}: {
  deltaPct: number | null;
  amberWhenUp?: boolean;
}) {
  if (deltaPct == null) {
    return (
      <span className="font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] text-[#7C887E]">
        sem base anterior
      </span>
    );
  }
  const isAmber = amberWhenUp && deltaPct > 0;
  const Icon = deltaPct < 0 ? ArrowDown : ArrowUp;
  return (
    <span
      className={`inline-flex items-center gap-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium tabular-nums ${
        isAmber ? 'text-amber-600' : 'text-[#7C887E]'
      }`}
    >
      <Icon className="h-[1em] w-[1em] shrink-0" aria-hidden />
      {formatDeltaPct(deltaPct)} vs anterior
    </span>
  );
}

/** Hero da rede (v3): marca/relógio/filtro + faixa de métricas. */
export function TvHero({ network, freshness, now, period, onPeriodChange }: TvHeroProps) {
  const vendas = useCountUp(network?.vendasHoje ?? 0);
  const hasData = network != null;
  const periodLabel = TV_PERIOD_LABEL[period];

  // Barra de meta (SECUNDÁRIA na v3): preenchimento = % do dia COMPLETO;
  // tick dourado = esperado agora (pró-rata).
  const fullDayPct =
    network && network.metaDia != null && network.metaDia > 0
      ? (network.vendasHoje / network.metaDia) * 100
      : null;
  const expected = expectedPctNow(now);
  const ratio = network?.pctMetaProRata != null ? network.pctMetaProRata / 100 : null;
  const barColor = metaBarColorFromRatio(ratio, now);

  const liveFresh = freshness.vendasLive.level === 'fresh';
  const liveTime = formatTimeHHMM(freshness.vendasLive.updatedAt);

  return (
    <header
      className="flex flex-col gap-4 border-b border-[#C5A065]/25 pb-4 lg:gap-5"
      data-testid="tv-hero"
    >
      {/* Linha 1 — marca + relógio/freshness/filtro global */}
      <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3">
        <div className="flex min-w-0 items-baseline gap-3">
          <span className="font-momma text-[clamp(0.875rem,1.05vw,1.875rem)] font-bold uppercase tracking-[0.3em] text-[#C5A065]">
            MOMMA
          </span>
          <span className="truncate font-serif text-[clamp(1rem,1.35vw,2.5rem)] font-semibold tracking-tight text-[#2D362E]">
            Torre de Controle
          </span>
        </div>
        <div className="flex flex-wrap items-center gap-x-4 gap-y-2 lg:gap-x-5">
          <span className={`inline-flex items-center gap-2 rounded-full px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium ${
            liveFresh
              ? 'bg-emerald-50 text-emerald-600'
              : 'border border-amber-400/40 bg-amber-50 text-amber-600'
          }`}>
            {liveFresh
              ? <><span className="h-2 w-2 rounded-full bg-emerald-400 animate-pulse" aria-hidden />{liveTime ? `atualizado ${liveTime}` : 'ao vivo'}</>
              : <><RefreshCw className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />{liveTime ? `atrasado · ${liveTime}` : 'atrasado'}</>
            }
          </span>
          <span className="font-momma text-[clamp(1.25rem,2vw,3.75rem)] font-light leading-none text-[#2D362E] tabular-nums">
            {formatTimeHHMM(now)}
          </span>
          <TvPeriodFilter period={period} onPeriodChange={onPeriodChange} />
        </div>
      </div>

      {/* Linha 2 — métricas: vendas | compras | perdas | alertas */}
      <div className="grid grid-cols-2 items-end gap-x-4 gap-y-4 lg:grid-cols-3 lg:gap-8">
        {/* Zona 1 — vendas da rede hoje + % vs ontem (principal) */}
        <div className="col-span-2 min-w-0 lg:col-span-1">
          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
            REDE · VENDAS HOJE
          </span>
          <div className="mt-1 flex flex-wrap items-end gap-x-4 gap-y-2">
            <span
              className="font-momma text-[clamp(2.25rem,4vw,7.5rem)] font-bold leading-none text-[#2D362E] tabular-nums"
              data-testid="tv-hero-sales"
            >
              {hasData ? formatCompactBRL(vendas) : '—'}
            </span>
            {network?.deltaOntem != null && (
              <span className="pb-1">
                <TvDeltaChip delta={network.deltaOntem} label="ontem" size="hero" />
              </span>
            )}
            {network?.deltaSemana != null && period === 'week' && (
              <span className="pb-1">
                <TvDeltaChip delta={network.deltaSemana} label="sem. ant." size="hero" />
              </span>
            )}
          </div>
          {/* Meta pró-rata — secundária desde a v3 */}
          <div className="mt-2 max-w-[36rem]">
            <TvMetaBar
              fillPct={fullDayPct}
              expectedPct={fullDayPct != null ? expected : null}
              color={barColor}
              size="card"
            />
            <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] leading-tight">
              {fullDayPct != null ? (
                <>
                  <span className="font-medium text-[#5F6F63]">
                    {Math.round(fullDayPct)}% da meta
                  </span>
                  <span className="text-[#7C887E]"> · esperado {expected}%</span>
                </>
              ) : (
                <span className="text-[#7C887E]">sem meta cadastrada</span>
              )}
            </p>
          </div>
        </div>

        {/* Zona 2 — marketing do período */}
        <div className="min-w-0">
          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
            MARKETING · {periodLabel}
          </span>
          <p
            className="mt-1 font-momma text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold leading-none text-[#2D362E] tabular-nums"
            data-testid="tv-hero-marketing"
          >
            {network ? formatCompactBRL(network.marketing.valor) : '—'}
          </p>
          <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] text-[#7C887E]">
            {network ? `${network.marketing.acoes} ${network.marketing.acoes === 1 ? 'ação' : 'ações'}` : '—'}
          </p>
        </div>

        {/* Zona 3 — perdas do período (R$ + itens; subir é desvio → âmbar) */}
        <div className="min-w-0">
          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
            PERDAS · {periodLabel}
          </span>
          <p
            className="mt-1 font-momma text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold leading-none text-[#2D362E] tabular-nums"
            data-testid="tv-hero-perdas"
          >
            {network ? formatCompactBRL(network.perdas.valor) : '—'}
            {network && (
              <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
                {' '}
                · {network.perdas.itens} {network.perdas.itens === 1 ? 'item' : 'itens'}
              </span>
            )}
          </p>
          <p className="mt-1">
            <TvHeroDeltaLine deltaPct={network?.perdas.deltaPct ?? null} amberWhenUp />
          </p>
        </div>

      </div>
    </header>
  );
}

